  "近戰": "Melee",
  "霰光杖": "Scatter Staff",
  "五發散射，近距離很痛": "Five-shot spread, painful up close",
  "散射": "Spread",
  "穿光矛": "Piercing Spear",
  "貫穿一整排敵人": "Pierces a whole line of enemies",
  "貫穿": "Pierce",
  "流火鏈": "Flame Chain",
  "中速連射的火星": "Medium-speed stream of sparks",
  "光線杖": "Beam Staff",
  "按住蓄力，放開射出貫穿光束，蓄越久越粗越痛": "Hold to charge, release for a piercing beam — longer charge, thicker and stronger",
  "蓄力": "Charge",
  "迴旋紙鏢": "Boomerang",
  "飛出去再飛回來，來回都會貫穿敵人": "Flies out and back, piercing both ways",
  "迴旋": "Boomerang",
  "長燈鞭": "Long Whip",
  "又長又窄的一條線，貫穿路徑上所有敵人": "A long thin line hitting every enemy on its path",
  "長鞭": "Whip",
  "油燈槍": "Oil Lamp Gun",
  "慢速單發，命中敵人會讓暖光冷卻縮短 0.3 秒": "Slow single shot; each hit cuts Warm Light's cooldown by 0.3 s",
  "補能": "Recharge",
  "紙盾刃": "Paper Shield Blade",
  "小範圍的近戰揮砍，揮砍時會擋掉敵方子彈": "Small melee slash that blocks enemy bullets while swinging",
  "守夜燈": "Night Watch Lamp",
  "穩定的單發光彈，在自己的光圈內傷害更高": "Steady single light shot; stronger inside your own light circle",
  "小火球": "Small Fireball",
  "連射的小火球，傷害 1.8": "Rapid small fireballs, damage 1.8",
  "影刃": "Shadow Blade",
  "長按 F 持續揮出近戰扇形（約每 0.25 秒一次）": "Hold F for continuous melee arcs (about every 0.25 s)",
  "近戰連砍": "Melee combo",
  "霜燈杖": "Frost Lamp Staff",
  "慢速近戰，擊退很強，傷害 6": "Slow melee with strong knockback, damage 6",
  "膨脹燈球": "Swelling Orb",
  "單發球體，飛出去會明顯脹大（半徑約 ×6），越大越痛（傷害 5 → 10）": "Single orb that swells in flight (radius about ×6); bigger hurts more (damage 5 → 10)",
  "漸大": "Growing",
  "增長光矛": "Growing Spear",
  "貫穿光矛，飛行中變粗，傷害越來越高（4 → 8）": "Piercing spear that thickens in flight, damage rising (4 → 8)",
  "貫穿・漸大": "Pierce・Growing",
  "火舞棍": "Fire Dance Staves",
  "兩根火棍（相差 180 度）會自己繞著你轉；按住 F 加速旋轉，傷害更高，但移動變慢": "Two fire staves (180° apart) orbit you; hold F to spin faster for more damage, but you move slower",
  "旋轉": "Spin",
  "紙扇": "Paper Fan",
  "展開扇面，射出三道會穿透的短程風刃（中華古代主題武器）": "Opens the fan to fire three short-range piercing wind blades (Ancient China weapon)",
  "風刃": "Wind blade",
  "連射燈球": "Burst Orbs",
  "一次連發 3 顆慢速膨脹燈球（飛行中變大、傷害 3 → 6），連發之間冷卻較長": "Fires 3 slow swelling orbs at once (grow in flight, damage 3 → 6) with a longer cooldown between bursts",
  "連發・漸大": "Burst・Growing",
  "毒瓶": "Poison Flask",
  "丟出一瓶毒液，落地形成毒池 3 秒：敵人站在裡面每秒受 2 點傷害並沾毒（之後 3 秒每秒再受 1 點）（詛咒沼澤主題武器）": "Throws a flask that makes a 3 s poison pool: enemies inside take 2 damage/s and get poisoned (then 1/s for 3 s) (Cursed Swamp weapon)",
  "拋擲・毒池": "Throw・Poison pool",
  "彎刀迴旋": "Scimitar Return",
  "擲出一把彎刀，弧線飛出去再飛回來，來回都會貫穿敵人並清除敵人光球；接住它會立刻重置冷卻（沙漠主題武器）": "Throws a scimitar in an arc and back, piercing both ways and clearing enemy orbs; catching it resets the cooldown (Desert weapon)",
  "小光點": "Wisp",
  "放開時小光點會自己衝向最近的敵人，撞到造成傷害（不用瞄準）；按住 F 讓它回到身邊繞著你轉，擋掉敵人的子彈，但不會攻擊": "On release the wisp rushes the nearest enemy and hits it (no aiming); hold F to keep it orbiting you and blocking bullets, but it won't attack",
  "自走・護盾": "Homing・Shield",
  "追光弓": "Seeking Bow",
  "按住連射，螢火會輕微追蹤最近的敵人，傷害略低於螢火弓": "Hold to rapid-fire; fireflies lightly home in on the nearest enemy, damage slightly below the Firefly Bow",
  "追蹤連射": "Homing auto-fire",
  "雙刃剪": "Twin Shears",
  "近身交叉斬：先斜斬、0.15 秒後反斬，第二刀傷害 +50%": "Close cross-slash: a diagonal cut, then a reverse cut 0.15 s later with +50% damage",
  "雙斬": "Double slash",
  "摺紙飛機": "Paper Plane",
  "紙飛機沿 S 曲線飛行，命中後裂成 2 張小紙片": "The plane flies in an S curve and splits into 2 paper scraps on hit",
  "曲線連射": "Curved auto-fire",
  "彈跳燈球": "Bouncing Orb",
  "慢速燈球，碰牆與障礙會反彈最多 3 次，每次反彈傷害 +20%（變身期間不能使用）": "Slow orb that bounces off walls and obstacles up to 3 times, +20% damage per bounce (unusable while transformed)",
  "彈跳": "Bounce",
  "沙漏鏢": "Hourglass Dart",
  "迴旋鏢，飛行路徑留下細沙，沙上的敵人緩速 30%（約 1 秒）": "Boomerang leaving sand on its path; enemies on the sand are slowed 30% (about 1 s)",
  "迴旋・緩速": "Boomerang・Slow",
  "花苞槍": "Bud Gun",
  "拋出花苞，落地或命中後開出小花，花粉 2 秒內持續傷害範圍內的敵人": "Lobs a bud that blooms on landing or hit; pollen damages enemies in range for 2 s",
  "開花": "Bloom",
  "銅錢鏢": "Coin Darts",
  "三枚銅錢小扇面散射；身上燈芯每 10 枚傷害 +0.2（最多 +1.5）": "Three coins in a small spread; +0.2 damage per 10 wicks carried (up to +1.5)",
  "枕頭": "Pillow",
  "慢速近戰重擊；命中使一般敵人昏睡 1 秒（Boss 與精英無效）": "Slow heavy melee hit; puts normal enemies to sleep for 1 s (no effect on bosses and elites)",
  "昏睡": "Sleep",
  "糖漿鞭": "Syrup Whip",
  "近距離揮鞭，命中的敵人被黏住減速 40%（2 秒）；連續命中同一隻黏性疊加，第 3 層暈 0.6 秒": "Close-range whip; hit enemies are stuck and slowed 40% (2 s); stacks on repeat hits, the 3rd stack stuns for 0.6 s",
  "近戰・黏": "Melee・Sticky",
  "乒乓砲": "Ping-Pong Cannon",
  "方形彈球，飛行距離較短（約 420），碰牆或障礙反彈後距離重新計算；最多反彈 3 次、每次傷害 +30%（4 → 8.8），之後或飛太遠就折返；彈球靠近時再按攻擊鍵接球，完美接球讓下一發 ×1.5；沒接到則重新裝填 1.2 秒": "Square ball with short range (about 420), range resets after each bounce; up to 3 bounces, +30% damage each (4 → 8.8), then it returns; press attack as it nears to catch it — a perfect catch makes the next shot ×1.5; a miss means a 1.2 s reload",
