  "守燈戰：這層只有這間房。先逛上方的商人，準備好了走到燈塔按 F 開始；打完 2 波休息一次，守住燈塔共打 4 波": "Guard battle: this floor is just this room. Visit the merchant above first; when ready, walk to the lighthouse and press F. Rest after 2 waves; 4 waves in total",
