  "三層，帶著小糖走到最後": "Three floors, take Xiaotang to the end",
  "糖果・守燈": "Candy: Guard",
  "每層一間大房，守住燈塔": "One big room per floor; defend the lighthouse",
  "電玩・無盡": "Arcade: Endless",
  "像素風，一層接一層越來越強": "Pixel style, stronger floor after floor",
  "電玩・逃離": "Arcade: Escape",
  "崩塌線從左邊追來": "A collapse line chases from the left",
  "未來・守燈": "Future: Guard",
  "未來・逃離": "Future: Escape",
  "字母書房（DLC2）": "Letter Study (DLC2)",
  "傳統玩法；選到才下載（約 30 KB）": "Classic play; downloaded when chosen (about 30 KB)",
  "DLC2 長線（字母書房＋彼岸）": "DLC2 Long Run (Letter Study + Other Shore)",
  "彼岸（DLC2）": "Other Shore (DLC2)",
  "傳統玩法；會模仿武器的影怪": "Classic play; shades that mimic weapons",
  "佛寺・修行路（DLC3）": "Temple: Path of Practice (DLC3)",
  "日本・觀光維護（DLC3）": "Japan: Tourism Upkeep (DLC3)",
