  "　每個部位（頭部／身體／燈具／掛飾）限 1 個，匯入代碼合成；每個部位首次解鎖花 10 紙片，之後免費更換。": "　One per part (head/body/lamp/charm); import a code to fuse; the first unlock of each part costs 10 paper, later swaps are free.",
  "貼上 LKC1:{…} 代碼": "Paste an LKC1:{…} code",
