  "最初的那一盞，顏色像傍晚的窗。": "The very first lamp, colored like a window at dusk.",
  "通關的人，才認得這種冷靜的光。": "Only those who have cleared it recognize this calm light.",
  "打倒五百隻影子之後，燈學會了安靜地發亮。": "After five hundred shades, the lamp learned to shine quietly.",
  "三位同伴的光混在一起，就是這個顏色。": "Mix the light of three companions and you get this color.",
  "洗過很多次，還是看得出來，是走過很多路的紅。": "Washed many times, you can still tell: a red that has walked many roads.",
  "沒有受過傷的人，才配得上這片海。": "Only the unhurt deserve this sea.",
  "每個職業都走完一遍，連披風都鍍上了光。": "Every class completed, even the cape is gilded with light.",
  "只差一個人，就能走完。": "Just one more person to finish.",
  "走得越遠，披風就越長。": "The farther you go, the longer the cape.",
  "折過一千隻紙鶴，願望還是同一個。": "A thousand cranes folded, the wish is still the same.",
  "風一來，扇子自己就開了。": "When the wind comes, the fan opens by itself.",
  "雨天擋雨，晴天擋太亮的燈。": "Shields rain on wet days, and too-bright lamps on sunny ones.",
  "別人的羽毛，自己的故事。": "Someone else's feather, your own story.",
  "第一刀，總是最猶豫。": "The first cut is always the most hesitant.",
  "剪下去的，都開成了花。": "Whatever is cut blooms into a flower.",
  "船不用水，用想像。": "The boat sails on imagination, not water.",
  "折到最後一次，才發現是王冠。": "On the final fold it turns out to be a crown.",
  "透明的，所以每一滴都藏不住。": "Transparent, so every drop shows.",
  "燈油是最貴的，所以壺也要。": "Lamp oil is the priciest, so the pot must be too.",
  "盾碎過很多次，金邊是補上去的。": "The shield broke many times; the gold edge is the mending.",
  "孩子們說，那是把星星關在罩子裡。": "The children say it's stars locked inside a shade.",
  "她說，這樣燈火看起來比較有精神。": "She says it makes the lamplight look livelier.",
  "燈芯留太長，就變成了火。": "Leave the wick too long and it becomes a flame.",
  "面具後面的人，從來不說自己是誰。": "The one behind the mask never says who they are.",
  "彎彎的，像一盞還沒點亮的燈。": "Curved, like a lamp not yet lit.",
  "雪落在鐘上，聲音就變軟了。": "Snow on the bell softens its sound.",
  "敲一下，整座山都聽見。": "One strike, and the whole mountain hears.",
  "永遠朝著燈的方向。": "Always facing toward the lamp.",
  "開店的人，也得先學會揉麵。": "Even a shopkeeper must first learn to knead dough.",
  "生意興隆，通四海。": "Thriving trade, reaching all seas.",
  "字寫壞了，就把燈蓋上，裝作什麼也沒發生。": "If the writing goes wrong, cover the lamp and pretend nothing happened.",
  "開在河的另一邊，卻替這一邊照著路。": "Blooming on the other bank, yet lighting the way on this one.",
  "每一塊積木，都替你記著一個字。": "Each block remembers a letter for you.",
  "花開的時候，沒有誰在數日子。": "When flowers bloom, no one counts the days.",
  "遮得住太陽，遮不住想說話的眼睛。": "It shades the sun, not the eyes that want to speak.",
  "有人點了很久，從沒想過要熄。": "Someone lit it long ago and never thought of putting it out.",
  "飄過去的，都是放下了的。": "What drifts away has been let go.",
  "洗了很多次，所以什麼都不再執著。": "Washed so many times, it clings to nothing.",
  "翻開的那一頁，永遠是你還沒讀過的。": "The page you open is always one you haven't read.",
  "擺渡的人不說話，只負責把你送到岸邊。": "The ferryman says nothing; he only carries you to shore.",
  "它不屬於這一岸，所以特別紅。": "It doesn't belong to this shore, hence its special red.",
  "頭上的三個點，是三個放下的念頭。": "The three dots on the head are three thoughts let go.",
  "泥裡長出來，卻一點也不髒。": "Grown from mud, yet not at all dirty.",
  "一針一線，都是別人放下的東西。": "Every stitch is something someone else put down.",
  "勝利的人不一定是最強的，是走出迷宮的。": "The victor isn't always the strongest, but the one who left the labyrinth.",
  "頭盔上的紅羽毛，是從碎掉的陶罐裡撿來的。": "The helmet's red plume was picked from a broken clay jar.",
  "雙耳瓶裡裝的不是酒，是一整個港口的黃昏。": "The amphora holds not wine but a whole harbor's dusk.",
  "一點橄欖油，就能點亮整個下午。": "A little olive oil lights a whole afternoon.",
  "神祇們都說，這件很適合你。": "The gods all say this suits you.",
  "最後一顆櫻桃，總是留給戴帽子的人。": "The last cherry is always saved for the one wearing the hat.",
  "融化之前，每一層顏色都很認真。": "Before melting, every layer of color is in earnest.",
  "畫面有點雪花，可是你的臉很清楚。": "The screen is a bit snowy, but your face is clear.",
  "接住的每一個球，都變成一枚硬幣。": "Every ball you catch turns into a coin.",
  "擋住的是光，看清的是距離。": "It blocks the light and reveals the distance.",
  "視野裡的數字，永遠比你快一步。": "The numbers in view are always a step ahead of you.",
  "河上開了一朵花，是給迷路的人看的。": "A flower blooms on the river, for the lost to see.",
  "一盞接一盞，全是同行的人。": "Lamp after lamp, all fellow travelers.",
  "抱著它，連噩夢都會睡著。": "Hold it and even nightmares fall asleep.",
  "醒著的人，才覺得這是夢遊。": "Only those awake call this sleepwalking.",
