  "；長線歷史最遠 第 ": "; furthest long-run floor ",
  "遊戲中途離開（匯出目前進度）請在遊戲中的暫停頁操作。": "To leave mid-run (export current progress), use the pause page in game.",
  "W／A 上一頁，S／D 下一頁，E 切換已達成／未達成，Q 切換分類，F 返回。達成後可以解鎖造型": "W/A previous page, S/D next page, E toggle done/not yet, Q change category, F back. Achievements unlock looks",
