  "的核心亮了起來，遠處的霓虹一齊閃爍。": "'s core lights up and the distant neon flickers together.",
  "投下硬幣——遊戲開始。": "Insert a coin — game start.",
  "在糖霜裡緩緩站起來，甜甜的香氣變得有點嗆。": "Slowly rises from the frosting; the sweet scent turns a bit acrid.",
