  "玩具們安靜了：工坊裡留下一把武器": "The toys fall quiet: a weapon is left in the workshop.",
  "聖誕樹已經亮了": "The Christmas tree is already lit",
  "每個裝飾 4 燈芯（共 3 個）：燈芯、燈油或強化；掛滿 3 個得燈火 +1 與精良強化。已掛": "4 wicks per ornament (3 total): wicks, lamp oil or an upgrade; hanging all 3 gives lamplight +1 and a premium upgrade. Hung:",
  "工坊已安靜": "The workshop is quiet",
  "按 F 啟動發條：巨大的胡桃鉗與 4 隻小怪出現；全部打倒得一把武器與燈芯": "Press F to wind the clockwork: a giant nutcracker and 4 minions appear; defeat them all for a weapon and wicks.",
  "禮物已送完": "The gifts are all delivered",
  "按 F 丟一份禮物（最多 5 份）：燈芯、燈油，偶爾跑出怪": "Press F to toss a gift (up to 5): wicks, lamp oil, and occasionally a monster.",
