  "花 3 燈芯換一份神祕禮物：50% 強化、30% 燈芯 +8、20% 空盒子（只有 1 燈芯）；只能一次": "Spend 3 wicks for a mystery gift: 50% upgrade, 30% wicks +8, 20% empty box (only 1 wick). One use only.",
