  "聖誕合唱團": "Christmas Choir",
  "站在合唱團旁邊（150 像素內）聽 5 秒，離開會倒退。聽完：燈火 +1、燈芯 +10": "Stand within 150 px of the choir and listen for 5 s; leaving rewinds the progress. When done: lamplight +1, wicks +10.",
