  "春之花環：站在花環旁等 5 秒": "Spring Wreath: wait by the wreath for 5 s.",
  "花已經開過了": "The flowers have already bloomed",
  "站在花環旁邊（150 像素內）等 5 秒，離開會倒退。完成：燈火 +1、燈芯 +10": "Stand within 150 px of the wreath for 5 s; leaving rewinds the progress. When done: lamplight +1, wicks +10.",
  "靠近花環（": "Get close to the wreath (",
  "花香暖暖的：燈火 +1、燈芯 +10": "The floral scent is warm: lamplight +1, wicks +10",
  "野餐墊：花 6 燈芯，吃一頓點心": "Picnic Mat: spend 6 wicks for a snack.",
  "點心吃完了": "The snacks are all eaten",
  "F 野餐（6 燈芯）": "F Picnic (6 wicks)",
  "野餐：燈火 +2、技能冷卻重置": "Picnic: lamplight +2, skill cooldown reset",
  "復活節（DLC5）": "Easter (DLC5)",
  "花叢裡一對長耳朵緩緩升起，後面是比樹還高的白色身影。": "A pair of long ears slowly rises from the flowers, and behind them looms a white figure taller than a tree.",
  "我把春天藏好了……你找得到，就拿去吧！": "I've hidden spring away... if you can find it, take it!",
  "稻草窩裡，一隻巨大的母雞站了起來，腳邊擠滿了毛茸茸的小雞。": "In the straw nest, a giant hen stands up, her feet crowded with fluffy chicks.",
  "咕咕！誰都不准碰我的孩子！": "Cluck! No one touches my children!",
  "只要小雞還圍著，雞媽媽就不怕傷害。": "As long as the chicks surround her, Mother Hen fears no harm.",
  "草地中央，一顆粉紅色的巨蛋靜靜立著，蛋殼上有一道細細的裂痕。": "In the middle of the meadow, a giant pink egg stands quietly, a thin crack running across its shell.",
  "咚……咚……裡面的人，等了好久，好久。": "Thump... thump... Whoever is inside has waited for so long, so very long.",
  "蛋殼裂開的瞬間，是最脆弱的時候。": "The instant the shell cracks is when it is most vulnerable.",
  "大範圍的弧形揮砍（復活節專屬，類似提燈刃）": "A wide arcing slash (Easter only; similar to the Lantern Blade).",
  "單發的彩蛋，傷害高（復活節專屬，類似燈焰杖）": "A single colored egg with high damage (Easter only; similar to the Flame Staff).",
  "按住連射花瓣，射速快（復活節專屬，類似螢火弓）": "Hold to rapid-fire petals at a fast rate (Easter only; similar to the Firefly Bow).",
  "五發花朵散射，近距離很痛（復活節專屬，類似霰光杖）": "Five scattered flowers that hurt up close (Easter only; similar to the Scatterlight Staff).",
  "貫穿一整排敵人的長矛（復活節專屬，類似穿光矛）": "A spear that pierces an entire row of enemies (Easter only; similar to the Piercing Spear).",
  "復活節：擊敗彩蛋兔": "Easter: defeat the Egg Bunny",
  "復活節：擊敗雞媽媽": "Easter: defeat Mother Hen",
  "復活節：擊敗巨型彩蛋": "Easter: defeat the Giant Easter Egg",
  "春日小幫手": "Spring Helper",
  "復活節：同一局完成彩蛋籃與彩繪工坊": "Easter: complete both the Egg Basket and the Painting Workshop in one run",
  "你找到了所有的蛋，也找到了春天。": "You found every egg, and you found spring too.",
  "風停了，花在你的燈光裡輕輕搖，天亮得比平常更早一些。": "The wind has stilled, and the flowers sway gently in your lamplight. Dawn arrives a little earlier than usual.",
