  "很久以前，世界由一盞大燈照亮。燈熄之後，黑暗裡長出了怪物。": "むかしむかし、世界は一つの大きな灯で照らされていた。灯が消えると、闇の中に怪物が生まれた。",
  "長線含 DLC 主題": "ロングランにDLCテーマを含める",
