  "W／S 選職業，F 開始冒險；C 造型，V 成就。遊戲中按 P 或 Esc 暫停。": "W/Sでクラス選択、Fで開始。Cでコスチューム、Vで実績。ゲーム中はPかEscでポーズ。",
