  "放棄這局，換職業": "あきらめてクラスを変える",
  "W／S 選擇，F 確定；P、Esc 繼續": "W/Sで選択、Fで決定。P・Escで再開",
  "滑鼠：角色跑向游標，按住暫停追隨　WASD：攻擊方向　F：攻擊／拿取　Q、E：換武器　空白鍵：職業技能": "マウス：カーソルへ走る（押し続けると停止）　WASD：攻撃方向　F：攻撃/拾う　Q・E：武器切替　スペース：クラススキル",
  "大燈就在眼前": "大きな灯が目の前に",
