  "米諾陶不是壞蛋，只是一個關了太久的人。別手軟，但也別忘了，你的燈還亮著。": "ミノタウロスは悪党じゃない。長く閉じ込められすぎただけの者だ。手加減はするな。だが、お前の灯がまだともっていることも忘れるな。",
  "米諾陶低下頭——站到牆的另一邊，讓牠撞上去！": "ミノタウロスが頭を下げた——壁の反対側に立って、激突させろ!",
  "米諾陶倒下，迷宮的牆一面一面變淡，露出外面的海。": "ミノタウロスが倒れ、迷宮の壁が一枚ずつ薄れて、外の海が見えてきた。",
