  "路人合掌：功德 +2（": "通行人が合掌した:功徳+2(",
  "路人經過：靠近按 F，布施 1 燈芯換 2 功德": "通行人が通りかかった:近づいてFで、灯芯1本を布施して功徳2を得る",
  "轉世：": "転生:",
  "踩過地上的星點，依序連起來，就能讓星座重新亮起。黑洞會把你往它那裡拉，記得保持距離。": "地面の星点を順に踏んでつなげれば、星座が再び輝く。ブラックホールが引き寄せてくるので、距離を保つこと。",
  "轉動一次：燈火 +2／技能冷卻重置並燈芯 +10／一份普通強化（隨機）；只能一次": "一度回す:灯火+2/スキルのクールダウンリセットと灯芯+10/通常強化1つ(ランダム)。1回のみ。",
  "近戰刺擊，擊退很強（希臘專屬）": "近接の突き。ノックバックが強い(ギリシャ専用)",
  "近戰橫掃，範圍很寬；揮動時順便把周圍 150 像素內的垃圾掃乾淨（日本專屬）": "範囲の広い近接の薙ぎ払い。振るたびに周囲150ピクセル以内のゴミも掃き清める(日本専用)",
  "近戰連擊": "近接連撃",
  "迷宮入口": "迷宮の入口",
  "迷宮最深處，黑色的影子低下頭，牛角刮過石牆，火花濺了一地。": "迷宮の最奥で、黒い影が頭を下げた。角が石壁をこすり、火花が一面に飛び散る。",
  "迷宮的入口。兩隻精英守衛醒來後會追出來；打倒後，迷宮深處會出現一把武器": "迷宮の入口。目覚めた二体のエリート番人が追ってくる。倒せば、迷宮の奥に武器が現れる",
  "迷宮的守衛趕來了": "迷宮の番人が駆けつけた",
  "迷宮的守衛醒了：打倒牠們，到迷宮深處拿武器": "迷宮の番人が目覚めた:倒して、迷宮の奥で武器を手に入れろ",
  "這一次，換我替你擋一下。": "今度は私があなたを守る番。",
  "這個事件已經結束了": "このイベントはもう終わりました",
  "這座城的燈一盞一盞暗了下來——不是沒有油，而是已經很久沒有人，為了誰點燈。": "この街の灯がひとつずつ暗くなっていく——油が尽きたのではなく、誰かのために灯をともす人が、もう長いこといないのだ。",
  "這座道場沒有出口。門只為累積了足夠功德的人打開。": "この道場に出口はありません。門は、十分な功徳を積んだ者のためにだけ開きます。",
  "這是新的星座。就叫它「燈火」吧。": "これは新しい星座だ。「灯火」と名付けよう。",
