  "遊客們回來了！今天的評價……應該不錯吧？": "観光客が戻ってきた!今日の評価は……悪くないはず?",
  "運作中。妖怪會來破壞它——修好的設施要保護好（血量": "稼働中。妖怪が壊しに来る——修理した施設は守ること(体力",
  "道場：圈內的影子放下得更快；長按 F 誦經，立刻度化周圍的影子（冷卻 15 秒）": "道場:円内の影はより早く手放す。Fを長押しで読経すると周囲の影を即座に度化(クールダウン15秒)",
  "遠處有一點很小很小的光，在輕輕地呼吸。那是你的燈，也是所有星座想回去的地方。": "遠くに、とても小さな光がそっと呼吸している。それはあなたの灯であり、すべての星座が帰りたがっている場所でもある。",
  "還剩最後一個。宇宙的中心，在等你。": "残るは最後の一つ。宇宙の中心が、お前を待っている。",
  "那是沒有被放下的念頭。": "あれは、手放されなかった雑念だ。",
  "那是百鬼夜行！今晚的遊客……是妖怪們自己啊！": "百鬼夜行だ!今夜の観光客は……妖怪たち自身だったのか!",
  "那是米諾陶——陶罐上所有故事的最後一頁。": "あれがミノタウロス——壺に描かれたすべての物語の、最後のページだ。",
  "那是觀音。她不會傷人，只會問你問題。": "あれは観音様だ。人を傷つけたりしない。ただ、問いを投げかけるだけ。",
  "酒神狂歡！10 秒內瞄準會亂飄，但燈芯一直掉": "バッカスの宴!10秒間、狙いが乱れるが、灯芯が降り続ける",
  "酒神狂歡": "バッカスの宴",
