  "鐘已經敲過了": "鐘はもう撞きました",
  "鐘聲一圈一圈散開。心裡的雜音，安靜了一點點。": "鐘の音が輪になって広がっていく。心の雑音が、少しだけ静まった。",
  "鐘聲響起：雜念散了一些": "鐘が鳴った:雑念が少し散った",
  "長按 F 的極近距離快打，範圍廣但很短（佛寺專屬；用它打倒敵人功德 +3）": "Fを長押しで撃つ超近距離の連打。範囲は広いが射程は極短(仏寺専用。倒した敵から功徳+3)",
  "長按 F 的連續小飛鏢，射程中等（日本專屬）": "Fを長押しで放つ連続の小手裏剣。射程は中程度(日本専用)",
  "長按 F 的遠程連射，射程遠但單發很輕（希臘專屬）": "Fを長押しで撃つ遠距離連射。射程は長いが一発は軽い(ギリシャ専用)",
  "長按 F，朝瞄準方向彈出一把扇形念珠，射程比一般短彈長（佛寺專屬；用它打倒敵人功德 +3）": "Fを長押しで、狙った方向に扇状の数珠を弾く。通常の短弾より射程が長い(仏寺専用。倒した敵から功徳+3)",
  "長柄近戰：窄而長的一記重擊，擊退很強（佛寺專屬；用它打倒敵人功德 +3）": "長柄の近接武器。細く長い重い一撃でノックバックが強い(仏寺専用。倒した敵から功徳+3)",
  "長椅：休息一下，燈火 +1": "ベンチ:ひと休みして、灯火+1",
  "開始後會依序出現 3 波衝撞怪；全部擊倒得燈火 +2 與精良強化": "開始すると突進する敵が3ウェーブ順に現れる。全て倒せば灯火+2と上等強化が得られる",
