  "黏人愛心": "まとわりつくハート",
  "黏人的來了！": "まとわりつくやつが来た!",
  "黏人的愛心會纏住你，別怕，揮開就好。雙胞胎要「一起」解決才算數——這是規矩。": "まとわりつくハートが絡みついてくるけど、怖がらず振り払えばいい。双子は「一緒に」倒さないと数に入らない——それがルール。",
  "黑暗慢慢裂開。星星一顆一顆飄回天上，連成了你從來沒見過的圖案——一盞提燈。": "闇がゆっくりと裂けていく。星がひとつずつ空へ戻り、見たこともない形になった——一つの提灯。",
  "黑色的人影在陶罐的表面一個接一個轉過身來。這一頁的故事，從市集開始。": "壺の表面で黒い人影がひとつずつ振り向く。このページの物語は、市場から始まる。",
  "（已敲）": "(撞いた)",
  "（已結束）": "(終了)",
