  "軌道轟炸！": "軌道爆撃!",
  "能量彈幕！": "エネルギー弾幕!",
  "蛋糕塔坍塌！": "ケーキタワーが崩れる!",
  "資料損毀": "データ破損",
  "錯誤 ERROR": "エラー ERROR",
  "當機了！射擊散開、視野變窄": "クラッシュした!弾が散らばり、視野が狭まる",
  "【守夜人專屬】增傷 +10%、光圈範圍 +15%，且燈火壓制自動施放（按空白鍵開關；關閉時會立刻手動施放一次，想自己抓節奏就保持關閉並在需要時再去開關）（占 2 層）": "【守夜人専用】ダメージ+10%、光輪の範囲+15%、さらに灯火制圧が自動発動(スペースキーで切り替え。オフにすると即座に手動で1回発動。自分のリズムで使いたい時はオフにしておき、必要な時に切り替える)(2段階分を占有)。",
  "【定光者專屬】第 1 層：光圈半徑 +25%、圈內傷害 ×1.4 → ×1.6；第 2 層：離開光圈後 1 秒內仍保有加成，最多同時 4 個光圈，技能施放的光圈會出現在玩家附近": "【定光者専用】第1段階:光輪の半径+25%、輪内ダメージ×1.4→×1.6。第2段階:光輪を出た後も1秒間ボーナスが残り、光輪は最大4つ同時に出せ、スキルの光輪はプレイヤーの近くに出現する。",
  "【蓄光者專屬】第 1 層：每次命中能量 +2 → +3，大招傷害 ×1.3；第 2 層：大招後 2 秒無敵，且 3 秒內被打到不扣能量": "【蓄光者専用】第1段階:ヒットごとのエネルギー+2→+3、必殺技のダメージ×1.3。第2段階:必殺技の後2秒間無敵になり、3秒間は被弾してもエネルギーが減らない。",
  "【手機操作】": "【スマホ操作】",
  "左下搖桿：移動　右下：攻擊／拿取／選擇（自動瞄準開＝按鈕；關＝搖桿，要拉到圈外才會改變方向）": "左下スティック:移動　右下:攻撃/拾う/選択(オートエイムON=ボタン、OFF=スティックで、輪の外まで引くと向きが変わる)",
  "攻擊上方：職業技能　技能旁：換武器（也可直接點畫面下方的武器欄）": "攻撃の上:クラススキル　スキルの隣:武器交換(画面下の武器欄をタップしてもよい)",
  "右上：小地圖　左上：暫停": "右上:ミニマップ　左上:一時停止",
  "F 開始守燈": "F 守りを開始",
  "十月的最後一個夜晚，墓園的門自己開了。南瓜燈一盞一盞地亮起來，卻沒有一盞，是為了照路。": "十月最後の夜、墓地の門がひとりでに開いた。カボチャのランタンがひとつずつともるが、どれも道を照らすためのものではない。",
  "南瓜燈": "カボチャのランタン",
  "提燈的旅人……今晚，連鬼也怕黑。你的燈，借我們靠一靠好嗎？": "提灯の旅人よ……今夜は幽霊でさえ暗闇が怖い。あなたの灯に、寄り添わせてもらえないかな?",
  "小心：這裡看不遠。靠近南瓜燈，或讓你的燈亮一點。": "気をつけて:ここは遠くまで見えません。カボチャのランタンに近づくか、灯を明るくしましょう。",
  "第二個夜晚更深了。月亮被雲吃掉一半，墓碑之間傳來骨頭互相敲打的聲音，像在數人頭。": "二つ目の夜はさらに深い。月は雲に半分食べられ、墓石の間から骨のぶつかり合う音が聞こえる。まるで人数を数えているようだ。",
  "最大的那一位，在鬼屋的最深處。他說，他不是想嚇人，只是沒人陪他過節。": "いちばん大きなあの人は、お化け屋敷の最奥にいる。人を驚かせたいんじゃない、お祭りを一緒に過ごす相手がいないだけだと言っていた。",
  "南瓜日記：今年的糖果，又被幽靈偷吃了一半。": "カボチャ日記:今年もお菓子を幽霊に半分つまみ食いされた。",
  "南瓜日記：骷髏們練習了一整年的「嘩啦」，只為了今晚嚇你一跳。": "カボチャ日記:骸骨たちは一年かけて「ガラガラ」を練習した。今夜あなたを驚かせるために。",
  "南瓜日記：蝙蝠不怕黑，牠只是怕被人當成吸血鬼。": "カボチャ日記:コウモリは暗闇が怖いんじゃない。吸血鬼と間違われるのが怖いだけ。",
  "南瓜日記：據說，最亮的南瓜燈裡，住著一個很久沒回家的小孩。": "カボチャ日記:いちばん明るいランタンには、長いこと家に帰っていない子供が住んでいるらしい。",
  "南瓜田": "カボチャ畑",
