  "萬聖節：視野有限——靠近南瓜燈，或讓你的燈亮一點": "ハロウィン:視界が限られています。カボチャのランタンに近づくか、灯を明るくしましょう",
  "召喚祭壇": "召喚の祭壇",
  "墓園夜襲": "墓地の夜襲",
