  "故事很溫暖：燈火 +1、燈芯 +8": "温かい物語:灯火+1、灯芯+8",
  "聽完有了勇氣：技能冷卻重置、強化「": "聞き終えて勇気が湧いた:スキルのクールダウンをリセット、強化「",
  "被嚇到了！鬼跳出來（先收下 14 燈芯）": "驚いた!幽霊が飛び出した(先に灯芯14本を受け取る)",
