  "暖身完畢：技能冷卻重置、強化「": "体が温まった:スキルのクールダウンをリセット、強化「",
  "壁爐裡掉出了襪子：燈芯 +15": "暖炉から靴下が落ちてきた:灯芯+15",
  "玩具們安靜了：工坊裡留下一把武器": "おもちゃたちが静まった:工房に武器が残された",
