  "每個裝飾 4 燈芯（共 3 個）：燈芯、燈油或強化；掛滿 3 個得燈火 +1 與精良強化。已掛": "飾り1つにつき灯芯4本(計3個):灯芯、灯油、または強化。3個とも飾ると灯火+1と上等強化。飾った数:",
  "工坊已安靜": "工房は静まりました",
  "按 F 啟動發條：巨大的胡桃鉗與 4 隻小怪出現；全部打倒得一把武器與燈芯": "Fでぜんまいを巻く:巨大なくるみ割り人形と小さな手下4体が現れる。全て倒すと武器と灯芯が得られる",
  "禮物已送完": "プレゼントは配り終えました",
  "按 F 丟一份禮物（最多 5 份）：燈芯、燈油，偶爾跑出怪": "Fでプレゼントを投げる(最大5個):灯芯、灯油、たまに怪物が出る",
  "已經暖和了": "もう温まりました",
  "站在壁爐旁邊（150 像素內）聽 6 秒，離開會倒退。結局：回血加燈芯／技能冷卻重置加強化／燈芯 +15": "暖炉から150ピクセル以内に立って6秒間過ごす。離れると進行が戻る。結果:回復+灯芯/スキルのクールダウンリセット+強化/灯芯+15",
