  "胡桃鉗張開大嘴——衝撞後的 3 秒是弱點，傷害 ×2！": "くるみ割り人形が大きく口を開ける——突進後の3秒は弱点、ダメージ×2!",
  "玩具兵列隊！": "おもちゃの兵隊、整列!",
