  "交換禮物：花 3 燈芯，換一份神祕禮物": "プレゼント交換:灯芯3本で謎のプレゼントと交換",
  "交換禮物": "プレゼント交換",
  "禮物已經拆開了": "プレゼントはもう開けました",
  "花 3 燈芯換一份神祕禮物：50% 強化、30% 燈芯 +8、20% 空盒子（只有 1 燈芯）；只能一次": "灯芯3本で謎のプレゼントと交換:50%で強化、30%で灯芯+8、20%で空箱(灯芯1本のみ)。1回のみ。",
  "F 交換（3 燈芯）": "F 交換(灯芯3本)",
