  "站在合唱團旁邊（150 像素內）聽 5 秒，離開會倒退。聽完：燈火 +1、燈芯 +10": "合唱団から150ピクセル以内に立って5秒間聞く。離れると進行が戻る。聞き終えると:灯火+1、灯芯+10",
