  "花 6 燈芯：燈火 +2、技能冷卻重置；只能一次": "灯芯6本:灯火+2、スキルのクールダウンリセット。1回のみ。",
  "F 買熱可可（6 燈芯）": "F ホットココアを買う(灯芯6本)",
  "熱可可：燈火 +2、技能冷卻重置": "ホットココア:灯火+2、スキルのクールダウンリセット",
  "耶誕節（DLC5）": "クリスマス(DLC5)",
  "耶誕節": "クリスマス",
  "發條玩具盒": "ぜんまいのおもちゃ箱",
  "雪橇的鈴聲由遠而近，一個巨大的紅色身影擋在路中間。": "そりの鈴の音が遠くから近づき、巨大な赤い影が道の真ん中に立ちふさがった。",
  "今年的禮物……全都送不出去了。來，你替我接住它們吧！": "今年のプレゼントは……ひとつも届けられなかった。さあ、お前が受け止めてくれ!",
  "工廠的烤箱門一扇扇打開，熱氣裡走出整排薑餅人。": "工場のオーブンの扉がひとつずつ開き、湯気の中からジンジャーブレッドマンがずらりと歩き出る。",
  "訂單沒做完，誰都別想走！出爐——": "注文がまだ終わってない、誰も帰さないぞ!焼きあがれ——",
  "只要薑餅人還站著，工廠長就有糖霜護體。": "ジンジャーブレッドマンが立っているかぎり、工場長は糖衣に守られている。",
  "玩具堆裡，一個比房子還高的木頭士兵慢慢轉過頭，發條咔啦咔啦地響。": "おもちゃの山の中で、家より背の高い木の兵隊がゆっくり振り向く。ぜんまいがカラカラと鳴った。",
  "咔、咔——想要我的心，就得先撬開我的嘴。": "カチ、カチ——私の心がほしければ、まず私の口をこじ開けてみろ。",
  "牠張開嘴巴的瞬間，是最脆弱的時候。": "口を開けた瞬間こそ、いちばん弱い時だ。",
  "拐杖糖": "キャンディケーン",
  "大範圍的弧形揮砍（耶誕節專屬，類似提燈刃）": "広範囲の弧を描く斬撃(クリスマス専用。提灯刃に似る)",
  "雪球砲": "雪玉砲",
  "單發的雪球，傷害高（耶誕節專屬，類似燈焰杖）": "単発の雪玉。高ダメージ(クリスマス専用。灯焔杖に似る)",
  "鈴鐺弓": "鈴の弓",
  "按住連射小鈴鐺，射速快（耶誕節專屬，類似螢火弓）": "長押しで小さな鈴を高速連射(クリスマス専用。蛍火弓に似る)",
  "冬青散彈": "ヒイラギの散弾",
  "五發冬青果散射，近距離很痛（耶誕節專屬，類似霰光杖）": "ヒイラギの実を5発散らして撃つ。近距離で強烈(クリスマス専用。霰光杖に似る)",
  "貫穿一整排敵人的冰錐（耶誕節專屬，類似穿光矛）": "一列の敵を貫くつらら(クリスマス専用。穿光槍に似る)",
  "送不出去的禮物": "届けられないプレゼント",
  "耶誕節：擊敗聖誕老人": "クリスマス:サンタクロースを倒す",
  "關掉烤箱": "オーブンを消す",
  "耶誕節：擊敗薑餅工廠長": "クリスマス:ジンジャーブレッド工場長を倒す",
  "撬開那張嘴": "あの口をこじ開けろ",
  "耶誕節：擊敗巨型胡桃鉗": "クリスマス:巨大くるみ割り人形を倒す",
  "聖誕小幫手": "クリスマスの小さな助っ人",
  "耶誕節：同一局完成許願聖誕樹與精靈工坊": "クリスマス:1回のプレイで願いのクリスマスツリーと妖精の工房を両方完了する",
  "雪停了。下一個節日的鈴聲，已經在路的盡頭響起。": "雪がやんだ。次のお祭りの鈴の音が、道の果てですでに鳴っている。",
  "謝謝你替我接住了那些禮物。今年，終於有人拆開它們。": "プレゼントを受け止めてくれてありがとう。今年はようやく、誰かがそれを開けてくれた。",
  "雪地上的燈一盞一盞地熄了，只剩下你的那一盞，安靜地亮到天亮。": "雪原の灯がひとつずつ消え、あなたの灯だけが残って、夜明けまで静かにともり続けた。",
  "雪化了，草地從泥土裡探出頭。風裡有花香，也有一點點巧克力的味道。": "雪が溶け、草が土から顔を出した。風には花の香りと、ほんのりチョコレートの匂いが混じっている。",
  "旅人！彩蛋全被藏起來了，連蛋殼都在亂跑——幫我找回春天好嗎？": "旅人さん!イースターエッグが全部隠されて、卵の殻まで走り回ってるの——春を取り戻すのを手伝ってくれる?",
  "花開得太用力，連空氣都是粉紅色的。籃子翻倒在草叢，蛋滾得到處都是。": "花が力いっぱい咲きすぎて、空気までピンク色だ。かごが草むらでひっくり返り、卵があちこちに転がっている。",
  "最大的那顆蛋……還沒有孵出來。牠一直在等一個敲門的人。": "いちばん大きな卵は……まだ孵っていない。ずっと、ノックしてくれる人を待っている。",
  "彩蛋便條：我把最漂亮的那顆藏在最顯眼的地方，結果大家都沒找到。": "卵のメモ:いちばんきれいな卵を、いちばん目立つ場所に隠したら、誰にも見つけてもらえなかった。",
  "彩蛋便條：小雞說，破殼的那一刻不是結束，是第一次看見天空。": "卵のメモ:ひよこは言う。殻を破る瞬間は終わりじゃない、初めて空を見る時だと。",
  "彩蛋便條：兔子洞很深，但盡頭有一盞跟你一樣的燈。": "卵のメモ:うさぎの穴は深いけれど、突き当たりにはあなたと同じ灯がある。",
  "彩蛋便條：春天不是被找到的，是被一起種出來的。": "卵のメモ:春は見つけるものじゃない、みんなで一緒に育てるものだ。",
